const root = $json ?? {};
const bodyRaw = root.body ?? root;
const body = (typeof bodyRaw === 'string') ? (JSON.parse(bodyRaw) || {}) : bodyRaw;
const eventValue = root.event ?? body.event ?? '';
const eventName = typeof eventValue === 'string' ? eventValue.toLowerCase() : '';
if (eventName === 'session.status') return [];
const event = (eventValue && typeof eventValue === 'object') ? eventValue : body;
const msg = (event.payload && typeof event.payload === 'object') ? event.payload : ((event.message && typeof event.message === 'object') ? event.message : event);
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const serialized = JSON.stringify(root);
const fallbackChat = (serialized.match(/\d{10,15}@(c\\.us|lid)/i) || [])[0] || '';
const rawChatId = String(msg.from ?? msg.chatId ?? msg.to ?? body.from ?? body.chatId ?? fallbackChat).trim();
const phone = rawChatId.replace(/@(c\.us|lid)$/i, '');
const fallbackText = (serialized.match(/\"(?:body|text|content)\"\s*:\s*\"([^\"]+)/i) || [])[1] || '';
const text = String(msg.body ?? msg.text ?? msg.content ?? body.body ?? body.text ?? fallbackText).trim();
const customer_name = String(msg.pushName ?? msg.notifyName ?? body.pushName ?? '');
const dedupeKey = String(msg.id ?? msg._data?.id?.id ?? body.id ?? '').trim();
if (dedupeKey && store.seen[dedupeKey]) return [];
if (msg.fromMe === true || body.fromMe === true || body.from_me === true) return [];
if (!phone || !text) return [];
if (dedupeKey) store.seen[dedupeKey] = Date.now();
return [{ json: { phone, text, customer_name, chat_id: rawChatId, raw: body } }];

const input = $('Normalizar mensagem').item.json;
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const key = input.phone;
let s = store.sessions[key];
if (!s || s.closed) s = { step: 'menu', items: [], mode: '', name: '', address: '', payment: '', observations: '', order_number: '' };
const text = String(input.text || '').trim();
const low = text.toLowerCase();
const menu = 'Ola! Bem-vindo ao Zelda PDV. 1-Pedido 2-Status 3-Cardapio 4-Feedback 5-Humano';
const out = { ...input, action: 'reply', reply: menu, items: s.items || [], mode: s.mode || '', name: s.name || '', address: s.address || '', payment: s.payment || '', observations: s.observations || '' };
if (!text) return [{ json: out }];
if (s.step === 'human') { out.action = 'human'; out.reply = 'Atendimento humano ativo. Aguarde uma mensagem da equipe.'; store.sessions[key] = s; return [{ json: out }]; }
if (s.step === 'menu') {
  if (/^(1|pedido|fazer pedido)\b/.test(low)) { s.step = 'mode'; out.action = 'reply'; out.reply = 'Sera entrega ou retirada no local? Responda entrega ou retirada.'; }
  else if (/^(2|status|consultar)\b/.test(low)) { s.step = 'status'; out.action = 'status'; out.reply = 'Informe o numero do pedido.'; }
  else if (/^(3|cardapio|cardapio digital|menu)\b/.test(low)) { out.action = 'reply'; out.reply = 'Cardapio digital: Zelda Burger R$ 28,90; X-Bacon Zelda R$ 34,90; Refrigerante Lata R$ 6,50. Para fazer pedido, responda 1.'; }
  else if (/^(4|elogio|reclamacao|feedback)\b/.test(low)) { s.step = 'feedback'; out.action = 'feedback'; out.reply = 'Envie seu elogio ou reclamacao em uma mensagem.'; }
  else if (/^(5|humano|atendente)\b/.test(low)) { s.step = 'human'; out.action = 'human'; out.reply = 'Vou transferir voce para um atendente humano. Informe o assunto.'; }
  else out.action = 'reply';
} else if (s.step === 'mode') {
  if (/entrega|delivery/.test(low)) { s.mode = 'delivery'; s.step = 'name'; out.reply = 'Informe seu nome completo.'; }
  else if (/retirada|retirar|local|pickup/.test(low)) { s.mode = 'takeout'; s.step = 'name'; out.reply = 'Informe seu nome completo.'; }
  else out.reply = 'Responda entrega ou retirada.';
  out.action = 'reply';
} else if (s.step === 'name') { s.name = text; s.step = s.mode === 'delivery' ? 'address' : 'payment'; out.action = 'reply'; out.reply = s.mode === 'delivery' ? 'Informe o endereco completo para entrega.' : 'Qual a forma de pagamento: dinheiro, cartao, pix ou Carteira/Fiado?'; }
else if (s.step === 'address') { s.address = text; s.step = 'payment'; out.action = 'reply'; out.reply = 'Qual a forma de pagamento: dinheiro, cartao, pix ou Carteira/Fiado?'; }
else if (s.step === 'payment') { if (!/dinheiro|cartao|cartão|pix|fiado|carteira/.test(low)) out.reply = 'Escolha dinheiro, cartao, pix ou Carteira/Fiado.'; else { s.payment = /fiado|carteira/.test(low) ? 'carteira_fiado' : /pix/.test(low) ? 'pix' : /cart/.test(low) ? 'cartao' : 'dinheiro'; s.step = 'items'; out.action = 'reply'; out.reply = 'Informe os produtos e quantidades. Exemplo: 1 Zelda Burger e 2 Refrigerante Lata.'; } }
else if (s.step === 'items') { const catalog = [{id:1001,title:'Zelda Burger',price:28.9},{id:1002,title:'X-Bacon Zelda',price:34.9},{id:1003,title:'Refrigerante Lata',price:6.5}]; const items = []; for (const p of catalog) { if (low.includes(p.title.toLowerCase())) { const m = low.match(new RegExp('(\\d+)\\s*(?:x\\s*)?' + p.title.toLowerCase().replace(/[.*+?^${}()|[\\]\\]/g,'\\$&'),'i')); items.push({ ...p, quantity: m ? Math.min(Number(m[1]),20) : 1 }); } } if (!items.length) { out.action = 'reply'; out.reply = 'Nao identifiquei os produtos. Use Zelda Burger, X-Bacon Zelda ou Refrigerante Lata.'; } else { s.items = items; s.step = 'observations'; out.action = 'reply'; out.reply = 'Ha alguma observacao? Exemplo: sem cebola, gelo e limao. Se nao houver, responda nao.'; } }
else if (s.step === 'observations') { s.observations = /^(nao|não|nenhuma|sem observacao|sem observacoes)$/.test(low) ? '' : text; s.step = 'confirm'; out.action = 'create_order'; out.reply = 'Pedido pronto para registro. Vou enviar os dados ao Zelda PDV.'; out.order_payload = { phone: input.phone, customer_name: s.name, address: s.address, mode: s.mode, payment: s.payment, items: s.items, observations: s.observations, channel: 'waha' }; }
else if (s.step === 'status') { out.action = 'status'; out.order_number = text.replace(/[^0-9A-Za-z-]/g,''); out.reply = 'Vou consultar o status do pedido.'; s.step = 'menu'; }
else if (s.step === 'feedback') { out.action = 'feedback'; out.feedback_message = text; out.feedback_type = /reclam|problema|ruim/.test(low) ? 'reclamacao' : 'elogio'; out.reply = 'Obrigado pelo retorno. Seu feedback foi registrado.'; s.step = 'menu'; }
else if (s.step === 'confirm') { out.action = 'create_order'; out.order_payload = { phone: input.phone, customer_name: s.name, address: s.address, mode: s.mode, payment: s.payment, items: s.items, observations: s.observations, channel: 'waha' }; }
store.sessions[key] = s;
return [{ json: { ...out, state: s.step } }];
